SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"status": "draft", "name": "朱元璋", "aliases": [], "era": "元末明初", "birth_year": null, "death_year": null, "description": "钟离人，少因饥疫丧家出家皇觉寺，1352年投郭子兴于濠州，后娶其养女。", "biography": null, "id": "3d83c7c6-23fc-5e89-9e9b-b70713a0a63e"}, {"name": "胡廷瑞", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "陈友谅江西丞相，降吴，康泰舅。", "biography": null, "status": "draft", "id": "802e1135-35a4-5a18-8000-e933e784a608"}, {"name": "邓愈", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1355年从朱元璋设伏擒陈埜先。", "biography": null, "status": "draft", "id": "5fbf3347-c8f3-5eaa-aa83-d0681e64b192"}, {"name": "蒋英（吴金华苗军元帅）", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "叛杀胡大海，掳掠金华城中人口逃投张。", "biography": null, "status": "draft", "id": "f51119c0-1650-5770-821e-6164a854dfdb"}, {"name": "胡大海", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "吴将，常州夹击援军。", "biography": null, "status": "draft", "id": "9608d085-9e6c-528f-bbb3-143306d2efb9"}, {"name": "王恺（胡大海幕属）", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "胡大海幕属，劝全军攻信州。", "biography": null, "status": "draft", "id": "d43bfd4c-f46d-5076-9995-2877c7996d14"}, {"name": "耿再成", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1354—55年从朱元璋守战六合和阳。", "biography": null, "status": "draft", "id": "e2654eb1-d625-5630-ab59-98ae745307ea"}, {"name": "孙炎", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "朱元璋下集庆后录用儒士。", "biography": null, "status": "draft", "id": "d1556d00-8ebc-507a-bf69-64f85ab8c866"}, {"name": "王道同（吴处州知府）", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "处州乱死。", "biography": null, "status": "draft", "id": "3aabb488-d111-55f4-af7f-0919afa15e34"}, {"name": "朱文刚（吴处州死难者）", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "处州叛乱被杀。", "biography": null, "status": "draft", "id": "e1af06b7-078f-5c9f-9029-50da4dac6ba3"}, {"name": "祝宗", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "陈友谅平章，先降吴后与康泰叛，终被志明杀。", "biography": null, "status": "draft", "id": "f2071a84-035f-5d3f-84f1-76476f890147"}, {"name": "康泰（陈友谅部将）", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1358年与邵宗邓克明攻邵武。", "biography": null, "status": "draft", "id": "bdad2800-1ce6-566a-9aa9-a7757a91d4ef"}, {"name": "叶琛", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "被舒穆嚕宜逊辟为军谋。", "biography": null, "status": "draft", "id": "e2253684-65f4-5429-b70d-c680b5a4de54"}, {"name": "万思诚", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "吴洪都行省都事，留辅邓愈，祝宗乱死。", "biography": null, "status": "draft", "id": "f1a22052-51dd-5bf3-a634-7cf8eebd5f29"}, {"name": "明玉珍", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "随州人，从徐寿辉，1357年领舟取重庆。", "biography": null, "status": "draft", "id": "4e68200c-5dfc-5811-96fa-2de59fb619e3"}, {"name": "邵荣", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "吴将，1358年与徐达取宜兴。", "biography": null, "status": "draft", "id": "ae6b35b0-33f6-57aa-9125-e1e57000d6ce"}, {"name": "徐达", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "濠州人，1353年随朱元璋南略。", "biography": null, "status": "draft", "id": "0f28446e-78b0-5db1-9677-98777005803e"}, {"name": "朱文正", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "朱元璋伯兄之子，1354年来归。", "biography": null, "status": "draft", "id": "56dcc7d8-3f0f-52f6-8948-26a4293a5819"}, {"name": "赵德胜", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "吴先锋，1357年擒张士德。", "biography": null, "status": "draft", "id": "8ed8be00-69e2-5fc0-8ae6-84985771c7d2"}, {"name": "察罕特穆尔", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "北庭后裔，居沈丘，与李思齐起兵，授汝宁达噜噶齐。", "biography": null, "status": "draft", "id": "59a5e251-37f4-5986-9511-962d04ceea90"}, {"name": "田丰（元末黄军万户）", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "黄军义兵万户，1357年转入红军，攻山东多地。", "biography": null, "status": "draft", "id": "20162b8d-f108-5d79-af95-a73003cf1e9a"}, {"name": "赵继祖（郭子兴军诈使）", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1355年诈为元使参与取和阳。", "biography": null, "status": "draft", "id": "beba6b9c-807c-54dd-bc22-18d83f839b94"}, {"name": "张昶（元户部尚书使吴者）", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "元户部尚书，携授官命出使朱元璋，被留建康。", "biography": null, "status": "draft", "id": "54d2e43b-fe7f-5493-b7b9-d069ea6c0d20"}, {"name": "张定边", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "陈友谅将，称帝时授太尉。", "biography": null, "status": "draft", "id": "f47481fa-0db7-5731-aa40-81d432adfef8"}, {"name": "吕珍", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "张士诚将，守常州、太湖水战。", "biography": null, "status": "draft", "id": "8a379102-9127-52ef-849f-d7d12d562416"}, {"status": "draft", "name": "韩林儿", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "韩山童之子，父被擒后与杨氏逃武安。", "biography": null, "id": "15a71da9-cd6f-5a0b-ba68-144469ebde18"}, {"status": "draft", "name": "陈友谅", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "沔阳渔家子，曾为县小吏，1351年来从徐寿辉，父名普才。", "biography": null, "id": "14cfdd00-af11-50e5-9fdb-22c478b7fdec"}, {"name": "谢再兴", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "吴中翼左副帅，1358年略石埭。", "biography": null, "status": "draft", "id": "79100aaf-285d-5acd-bd5e-9cae09a1225b"}, {"name": "张士诚", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "白驹场盐民，率众起兵，陷高邮称诚王建周。", "biography": null, "status": "draft", "id": "7fbe0af4-cc39-5fb7-9fa8-c94e110ad986"}, {"name": "刘齐（吴吉安守将）", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "1362年随诸将守吉安的参政。", "biography": null, "status": "draft", "id": "b8fea5d8-d0a7-5c59-837b-d579377f0e5b"}, {"name": "朱叔华", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "1362年任吉安知府。", "biography": null, "status": "draft", "id": "d7ac6dc0-f383-538c-9744-eb4c8a658251"}, {"name": "董曾（吴无为知州）", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "招民复业，城陷拒降被沉江。", "biography": null, "status": "draft", "id": "c3f772a3-b69f-58eb-9075-9f8c49cddba2"}, {"name": "俞通海", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1355年导巢湖军附朱元璋，领水军渡江。", "biography": null, "status": "draft", "id": "eff73aa1-e4e3-5022-b155-bf9d88812371"}, {"name": "常遇春", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "怀远人，1355年投朱元璋、采石先登。", "biography": null, "status": "draft", "id": "51d50a75-07e1-574f-b22d-1fded66288ff"}, {"name": "理（陈友谅次子）", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "陈友谅次子，父死在武昌被张定边立帝，后降吴。", "biography": null, "status": "draft", "id": "95a1b1a7-8490-5130-923c-2219a20204f5"}, {"name": "刘基", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "青田人，反对招抚方国珍被谪，曾任儒学副提举。", "biography": null, "status": "draft", "id": "bb5b8872-dbd3-576b-b02d-3b844e5a38e7"}, {"name": "李善长", "aliases": [], "era": "元末明初", "birth_year": null, "death_year": null, "description": "1353年受朱元璋留为幕书记。", "biography": null, "status": "draft", "id": "fcb986aa-d440-5732-984a-f4c744f5a06d"}, {"name": "汪河（吴中书省都事）", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "朱元璋遣其送尹焕章返汴。", "biography": null, "status": "draft", "id": "fd89e466-8724-5c7b-a19b-5253b56834ec"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "朱元璋入龙兴留降官抚民", "description": "朱元璋从九江往龙兴，胡廷瑞、祝宗先献陈朝官印和军民粮数，再率官属迎接。朱保留旧职，军纪严明，百姓安定。他拜孔庙、游铁柱观，宴滕王阁，次日令赈恤孤寡，把陈友谅所养鹿放归西山。", "start_year": 1362, "end_year": 1362, "time_original": "《续资治通鉴》卷216；本事原载纪年折合公元1362年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4ae2ecd1-cb4c-57ea-96a3-45461d745240"}, {"title": "朱元璋向龙兴百姓宣布安民措施", "description": "朱元璋在龙沙台召集百姓，称胡廷瑞先行归降，使大家免受战祸。他宣布革除陈友谅统治下的军需负担，劝百姓各安本业，不违法，也不要结交权贵扰害他人。百姓感到欣悦。", "start_year": 1362, "end_year": 1362, "time_original": "《续资治通鉴》卷216；本事原载纪年折合公元1362年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bbfc8e34-8245-59d4-8939-67dea805e75e"}, {"title": "吴改洪都城防留邓愈等守", "description": "朱元璋定洪都后，以城西南临水易受攻，令内移三十步，东南扩二里余。邓愈任江西参政留守，万思诚为都事辅佐；胡廷瑞、张民瞻、廖永坚、傅瓛、潘友庆等随朱还建康。", "start_year": 1362, "end_year": 1362, "time_original": "《续资治通鉴》卷216；本事原载纪年折合公元1362年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "aa02e234-6329-5595-b263-6c53980146ab"}, {"title": "蒋英等叛乱，胡大海、王恺等遇害", "description": "金华苗军蒋英、刘震、李福叛乱，诱胡大海出来观看弩弓。蒋英借钟矮子假装告状的机会，以铁锤击倒胡大海，斩其首，又杀死其子关住。王恺拒绝投降，刘震曾想保全他，吴得真却劝杀以绝后患。王恺及其子寅、章诚、高子玉皆死难。", "start_year": 1362, "end_year": 1362, "time_original": "《续资治通鉴》卷216；本事原载纪年折合公元1362年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a37a5fc5-7c9f-539e-ac19-9b7a3ffc5acf"}, {"title": "李佑之等叛处州，耿再成、孙炎等死难", "description": "李佑之、贺仁得得知金华叛乱后，也占据处州作乱，杀死耿再成、孙炎、王道同、朱文刚。耿再成仓促收兵迎战，连断来军长槊后战死。孙炎被囚后拒降，也不受酒和炙雁，坚持穿着朱元璋所赐衣服赴死。朱文忠派王祐率兵驻缙云，准备进讨。", "start_year": 1362, "end_year": 1362, "time_original": "《续资治通鉴》卷216；本事原载纪年折合公元1362年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6c128520-bf6b-50f4-9ebe-cf7b52d04174"}, {"title": "祝宗、康泰反叛洪都，万思诚、叶琛遇害", "description": "祝宗、康泰不满归附朱元璋，胡廷瑞担忧他们生变，暗中向朱元璋报告。朱元璋命两将赴湖广听徐达调遣，军行至女儿港时反叛，掠取商船布匹作旗号，袭破洪都。邓愈率数十骑边战边逃，返回建康，万思诚、叶琛遇害。朱元璋闻叶琛死讯哀悼，命徐达从汉阳回军讨乱。", "start_year": 1362, "end_year": 1362, "time_original": "《续资治通鉴》卷216；本事原载纪年折合公元1362年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7ade46ed-a8ff-5ed2-8d44-cbbd1b557a2f"}, {"title": "明玉珍称帝，设置官职并定赋税", "description": "明玉珍在蜀称帝，国号大夏，改元天统，立妻彭氏为后、子升为太子。仿周设六卿，以戴寿、万胜、张文炳、向大享、莫仁寿、吴友仁、邹兴、刘楨分任，牟图南掌翰林。分蜀八道，税取十分一，开廷试、设雅乐，制度出于刘楨安排。", "start_year": 1362, "end_year": 1362, "time_original": "《续资治通鉴》卷216；本事原载纪年折合公元1362年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7ec5a9a6-59a4-59b0-8b9d-6df1886c3d7c"}, {"title": "邵荣等收复处州，李佑之、贺仁得身亡", "description": "邵荣与王佑、胡深进攻处州，焚烧东北门后攻入城中。李佑之自杀，贺仁得逃到缙云，被农民捆送建康处死。邵荣留下王佑守城，随后返回。", "start_year": 1362, "end_year": 1362, "time_original": "《续资治通鉴》卷216；本事原载纪年折合公元1362年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "588367c4-d2e8-551a-a51d-eaefe76b3b39"}, {"title": "徐达收复洪都，祝宗逃走、康泰获宥", "description": "徐达攻破洪都，祝宗逃往新淦投奔邓克明。康泰逃往广信，被俘后送到建康。朱元璋念他是胡廷瑞的外甥，特别赦免。", "start_year": 1362, "end_year": 1362, "time_original": "《续资治通鉴》卷216；本事原载纪年折合公元1362年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bd7a8477-9edb-57ee-a177-e5eafc175753"}, {"title": "朱文正等分职守洪都，加强城防", "description": "朱元璋命朱文正统领赵德胜等，与邓愈共同驻守洪都。阮弘道任郎中，李胜任员外郎，汪广洋任都事，前往辅助，程国儒任洪都知府。朱文正到任后增修城墙、浚治城池，严加守备。", "start_year": 1362, "end_year": 1362, "time_original": "《续资治通鉴》卷216；本事原载纪年折合公元1362年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "693f9766-6a65-5019-b811-2e1d60d6d043"}, {"title": "田丰、王士诚设谋，察罕特穆尔被刺杀", "description": "益都久攻未下，田丰、王士诚再次谋叛，诱请察罕特穆尔到营中察看。众人劝他不要去，或带力士护卫，察罕特穆尔认为应推心待人，拒绝劝告，仅以轻骑十一人赴营，被王士诚刺死。田丰、王士诚逃入益都，军中推库库特穆尔为总兵官，继续围城。", "start_year": 1362, "end_year": 1362, "time_original": "《续资治通鉴》卷216；本事原载纪年折合公元1362年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e9147742-8164-5e83-8953-b1500249c951"}, {"title": "邵荣、赵继祖谋乱，被朱元璋处死", "description": "邵荣、赵继祖谋在三山门阅兵时伏击朱元璋。朱元璋改道返回，伏兵未发。部下宋国告变，朱元璋当面诘问得实，起初只将二人拘禁，不想立即杀死。常遇春坚请处死，朱元璋设酒食、流泪诀别后，将二人处刑。", "start_year": 1362, "end_year": 1362, "time_original": "《续资治通鉴》卷216；本事原载纪年折合公元1362年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b62bec0c-3c9f-553f-8651-3c616cc1c161"}, {"title": "朱元璋留用元使张昶", "description": "元廷派张昶携官服、御酒及授朱元璋江西平章的诏命，从海路到庆元。方国珍派燕敬通报，未获答复，又将张昶送往福建雅克布哈处。王溥奉命招张昶前来，刘绍先迎候同行，到达建康。张昶见朱元璋不拜，受到斥责；朱元璋随后留他在馆舍，询问政事，认为其才可用，便留下任用。", "start_year": null, "end_year": null, "time_original": "《续资治通鉴》卷216附叙，确年未载。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2169a56b-b5b9-5dda-8ce5-ec38e9289a93"}, {"title": "朱元璋以康茂才屯田为例，督促各军开垦", "description": "朱元璋此前让将领分地屯田，只有康茂才积谷充足。朱元璋以康茂才收获一万五千余石、供应军粮后仍余七千石为例，认为其他将领耕种不够勤勉，下令及时督军开垦，以充实军粮。", "start_year": 1363, "end_year": 1363, "time_original": "《续资治通鉴》卷217；本事原载纪年折合公元1363年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "841a6ab1-5c67-5307-9508-308ea9c58d1f"}, {"title": "江爵引陈友谅军攻陷饶州，穆燮死难", "description": "饶州守将于光与吴弘、吴毅不和，江爵乘机引陈友谅的将领张定边、蒋必胜来攻。守将仓促间没有防备，纷纷逃走，统管饶州军务的理问穆燮死难，杨宪逃回建康。", "start_year": 1363, "end_year": 1363, "time_original": "《续资治通鉴》卷217；本事原载纪年折合公元1363年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "90e211a5-6aa3-5362-b4c0-2e43b2bb0d43"}, {"title": "朱元璋击败吕珍，解安丰之围并接走韩林儿", "description": "朱元璋与徐达、常遇春救援安丰时，吕珍已经破城，杀死刘福通，结营迎战，并先击败救援军的左右两军。朱元璋命常遇春从侧面进攻，三战皆胜，常遇春又击败前来助战的左君弼。敌军退去后，朱元璋发粮救济城中饥民，接小明王韩林儿到滁州居住，再命徐达围攻庐州。竹昌、忻都趁机进入安丰。", "start_year": 1363, "end_year": 1363, "time_original": "《续资治通鉴》卷217；本事原载纪年折合公元1363年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c3185ad0-87ac-5915-971f-0adae572cb6e"}, {"title": "陈友谅率大舰围洪都，朱文正分派将领守门", "description": "陈友谅率全部军队，携家属、百官，乘高数丈、分三层、橹箱裹铁的大舰进攻洪都。城墙此前已向远离江边的方向内移三十步，巨舰不能再靠城让士卒攀登，陈友谅便改为围城。朱文正居中调度，派邓愈、赵德胜、薛显、牛海龙等分别守卫各门。", "start_year": 1363, "end_year": 1363, "time_original": "《续资治通鉴》卷217；本事原载纪年折合公元1363年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8ddb6b65-eeea-5ff4-a197-6cda5d2830dc"}, {"title": "谢再兴据诸全反叛，杀死栾凤夫妇", "description": "谢再兴在诸全反叛，杀死知州栾凤，栾凤的妻子王氏用身体护住丈夫，也一同被杀。李梦庚被捕，陈元刚等投降张士诚，胡士明抛下家人逃往建康。朱文忠派胡德济驻兵五指山，亲率二千精兵往来支援，朱元璋任命胡德济为浙江参政。王克瑀外出侦察，遇到张士诚军，被俘后死去。谢再兴此前因两名亲信私通杭州被处死，又因李梦庚职位在自己之上而怀恨。", "start_year": 1363, "end_year": 1363, "time_original": "《续资治通鉴》卷217；本事原载纪年折合公元1363年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "eb9f62b1-8447-54a1-a79c-03af312b8275"}, {"title": "李明道开门内应，陈友谅军攻陷吉安", "description": "蒋必胜、饶鼎臣攻陷吉安。李明道与曾万中兄弟不和，暗中邀蒋必胜来攻，举火作内应，打开西门迎军入城，杀死刘齐、朱叔华。曾粹中逃亡，被仇家黄如渊捕获，送给饶鼎臣后被杀。蒋必胜又攻破临江，擒获赵天麟，赵天麟不肯屈服，也被杀。", "start_year": 1363, "end_year": 1363, "time_original": "《续资治通鉴》卷217；本事原载纪年折合公元1363年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "db3926fc-1f20-5ed4-859e-ceec88d84be9"}, {"title": "董曾守无为，拒降后被沉入江中", "description": "陈友谅军攻陷无为，知州董曾被逼投降，不肯屈服，遭捆绑后沉入江中。董曾此前曾招集流亡百姓，让他们恢复生业，百姓因此安定。", "start_year": 1363, "end_year": 1363, "time_original": "《续资治通鉴》卷217；本事原载纪年折合公元1363年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2ebc0e3e-c5ab-55f8-aa95-8da20781fed9"}, {"title": "朱元璋撤去庐州围军，亲率水军救洪都", "description": "朱元璋命徐达、常遇春停止围攻庐州，亲率二十万水军救援洪都。徐达、常遇春、冯国胜、廖永忠、俞通海随行，冯国胜的船被风吹翻后，被遣回建康。大军到湖口，戴德奉命守泾江口，另一路军队守南湖嘴，又调信州兵守武阳渡，截断陈友谅的退路。", "start_year": 1363, "end_year": 1363, "time_original": "《续资治通鉴》卷217；本事原载纪年折合公元1363年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "19048fa0-8bc2-5ece-8665-0cc39c786ca7"}, {"title": "陈友谅解洪都之围，朱元璋分十一队迎战", "description": "洪都被围八十五天，陈友谅听说朱元璋援军到来，便撤去围城军，进入鄱阳湖迎战。两军在康郎山相遇，陈友谅将巨舰首尾相连。朱元璋认为这样不便进退，便将水军分为十一队，下令靠近敌船时先发火器，再用弓弩，接上敌船后再用短兵器作战。", "start_year": 1363, "end_year": 1363, "time_original": "《续资治通鉴》卷217；本事原载纪年折合公元1363年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "62e2138e-a1ca-5849-b33a-1c0c903bd3f2"}, {"title": "鄱阳湖首战徐达、俞通海等破敌，韩成等人战死", "description": "徐达、常遇春、廖永忠等进攻，徐达击败敌军前部，杀死一千五百人，夺得一艘巨舰。俞通海乘风放火，烧毁敌船二十余艘。徐达的船起火，仍奋力作战，朱元璋派船救援。张定边突袭朱元璋搁浅的座船，被常遇春射伤；俞通海驶来救援，激起的水使座船脱浅。韩成、宋贵、陈兆先、万国胜等战死。廖永忠追击张定边，常遇春的船后来也脱离浅滩。傍晚，朱元璋重申军令，并派徐达回守建康，防备张士诚。", "start_year": 1363, "end_year": 1363, "time_original": "《续资治通鉴》卷217；本事原载纪年折合公元1363年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5109c21f-00f9-5d0d-99a4-df02f5e1457b"}, {"title": "朱元璋采纳郭兴的火攻建议，友仁、友贵等被烧死", "description": "陈友谅用锁链连接巨舰，朱元璋的小船难以仰攻，连战三天后陷入危急。朱元璋处死十余名退军队长，仍不能止住退势。郭兴认为并非将士不用命，而是船只大小悬殊，建议火攻。朱元璋采纳，让七艘船载火药和披甲草人，乘东北风放火冲向敌船，后面另备小船供敢死士撤走。敌军水寨数百艘船被烧毁，陈友谅的弟弟友仁、友贵及陈普略等被烧死，朱元璋军乘势又斩杀二千余人。", "start_year": 1363, "end_year": 1363, "time_original": "《续资治通鉴》卷217；本事原载纪年折合公元1363年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a3cd0ffa-1d26-5fa8-a842-df061098cff3"}, {"title": "朱元璋采纳俞通海建议，移军扼上游，陈军两将投降", "description": "朱元璋拒绝将领们退军休整的请求，采纳俞通海因湖水浅而移军控制上游的建议，夜间让每船点一盏灯，相随渡过浅水，天亮时全部通过，停泊左蠡。陈友谅也移军渚矶，相持三天后，左右金吾将军先后投降。此前，两人分别主张留船再战和烧船登陆，陈友谅反复犹豫，使两将忧惧。", "start_year": 1363, "end_year": 1363, "time_original": "《续资治通鉴》卷217；本事原载纪年折合公元1363年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "865bea1c-7a96-5e54-8068-35f28ca1a782"}, {"title": "朱元璋写信责陈友谅，陈友谅令杀俘，朱元璋放还俘虏", "description": "朱元璋写信给陈友谅，自称先前曾放还池州俘虏，希望各安一方，是陈友谅先挑起战争，并催他决战。陈友谅愤怒，扣留使者，下令将俘获的朱元璋将士全部杀死。朱元璋听说后，放出所俘的陈友谅军士，对伤者给药治疗，全部遣返，又下令以后俘获敌军都不准杀，并祭奠陈友谅的弟侄及阵亡将士。", "start_year": 1363, "end_year": 1363, "time_original": "《续资治通鉴》卷217；本事原载纪年折合公元1363年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e3f86907-4367-5ed3-8d8e-168796a6e135"}, {"title": "陈友谅中箭身亡，善儿被俘，理在武昌被立为帝", "description": "陈友谅想返回武昌，率百余艘楼船先被南湖嘴守军拦住，后来冲出湖口。朱元璋指挥各军用火船、火筏追击，战至泾江口。随后有降卒报告，陈友谅在小船上被流箭射穿眼睛及头颅而死。朱元璋军乘势俘获太子善儿、姚天祥，陈荣等率五万余人投降。张定边夜间用小船载陈友谅的尸体及其次子理返回武昌，立理为帝，改元德寿。", "start_year": 1363, "end_year": 1363, "time_original": "《续资治通鉴》卷217；本事原载纪年折合公元1363年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bf70c988-817d-56c8-aee5-5d77930b29c8"}, {"title": "朱元璋返回建康，赐常遇春、廖永忠田地", "description": "朱元璋从湖口返回建康，赐给常遇春、廖永忠田地，其余将士则按等级分赐金帛。", "start_year": 1363, "end_year": 1363, "time_original": "《续资治通鉴》卷217；本事原载纪年折合公元1363年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "90dcf48f-e033-5d17-9337-1af5c7d1af45"}, {"title": "朱元璋向刘基承认，救安丰曾冒险", "description": "朱元璋向刘基承认，先前不听劝阻去救安丰，实在冒险。倘若陈友谅趁建康空虚，顺江进攻，自己就会进退无路；陈友谅却选择围攻洪都，朱元璋认为这是失策。", "start_year": 1363, "end_year": 1363, "time_original": "《续资治通鉴》卷217；本事原载纪年折合公元1363年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f20d2fc0-0700-5288-9402-7601d3402196"}, {"title": "朱元璋留李善长、邓愈守建康，亲征武昌", "description": "朱元璋命李善长、邓愈留守建康，亲率常遇春、康茂才、廖永忠、胡廷瑞等到武昌征讨陈理。", "start_year": 1363, "end_year": 1363, "time_original": "《续资治通鉴》卷217；本事原载纪年折合公元1363年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "18edb99a-8a1f-51d8-93ac-807d84cf75de"}, {"title": "张士诚自行称吴王，拒绝提供海运粮食", "description": "张士诚力求王爵，江浙丞相达实特穆尔怕遭报复，代他上奏，朝廷始终没有答复。张士诚便自行称吴王，尊母亲曹氏为太妃，修建宫殿、设置官属，将平江改为隆平府。元廷派户部侍郎博囉特穆尔等来征海运粮食，张士诚拒绝。当时建康、平江分称西吴、东吴，张士诚仍奉元朝年号，却实际上自行据守。", "start_year": 1363, "end_year": 1363, "time_original": "《续资治通鉴》卷217；本事原载纪年折合公元1363年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "664f4466-7856-5d00-a1f5-e8f038d170d0"}, {"title": "朱元璋围攻武昌，水陆封锁进出道路", "description": "朱元璋来到武昌，命常遇春等分兵四门，立栅围城，又在江上连船组成长寨，截断进出道路。他另派军队进取汉阳、德安，湖北各郡随后归降。", "start_year": 1363, "end_year": 1363, "time_original": "《续资治通鉴》卷217；本事原载纪年折合公元1363年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "55d0b806-2a9e-53e7-84b1-04936d070549"}, {"title": "朱元璋即吴王位，设官任命左右相国", "description": "李善长、徐达等劝进，朱元璋起初以战争未息、百姓尚未恢复生业为由推辞，众人再三请求，他才即吴王位，设置各官署及中书省。他任李善长为右相国、徐达为左相国，常遇春、俞通海为平章政事，汪广洋为右司郎中、张昶为左司郎中。", "start_year": 1364, "end_year": 1364, "time_original": "《续资治通鉴》卷217；本事原载纪年折合公元1364年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "32d4b701-3d37-5cef-b376-18216b22d86b"}, {"title": "罗复仁劝降陈理，朱元璋接纳并保全降众", "description": "朱元璋派陈友谅的旧臣罗复仁入城劝降，答应保全陈理性命。罗复仁入城后与陈理相对痛哭，传达朱元璋的意思。张定边也知道无法坚持，陈理便袒露上身、口衔玉璧，率张定边等出城投降。朱元璋见陈理年幼，扶起他，安慰说不治他的罪，又派人慰问陈友谅父母，准许陈理自取府库物资，让官属及家人带行装出城。", "start_year": 1364, "end_year": 1364, "time_original": "《续资治通鉴》卷217；本事原载纪年折合公元1364年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e5030d02-a912-513b-8441-6a8057c96bec"}, {"title": "武昌投降后，朱元璋赈济百姓、设湖广行省", "description": "武昌被围六个月后投降，士卒不敢入城，市井安定。朱元璋发米救济饥民，召父老安抚。汉、沔、荆、岳等郡县随后归降，于是设湖广行省，任杨璟为参政，留守当地。", "start_year": 1364, "end_year": 1364, "time_original": "《续资治通鉴》卷217；本事原载纪年折合公元1364年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d4fb71cb-3499-52f1-b97a-941416c3ce53"}, {"title": "朱元璋一方设置起居注、给事中", "description": "朱元璋一方设置起居注、给事中。", "start_year": 1364, "end_year": 1364, "time_original": "《续资治通鉴》卷217；本事原载纪年折合公元1364年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "337f4991-7e08-56ed-95e8-6c556211a6e5"}, {"title": "徐达、常遇春攻克庐州", "description": "庐州被围已久，军民饥困。张焕、贾丑暗中联系徐达，请他进攻东门，自己在城内接应。徐达、常遇春率军猛攻东门，城中军队都赶去救援，张焕便斩断吊桥、打开西门，引徐达军入城。吴副使及左君弼未具名的母亲、妻子、儿子被押送建康，指挥戴德受命留守庐州。", "start_year": 1364, "end_year": 1364, "time_original": "《续资治通鉴》卷218；本事原载纪年折合公元1364年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9d3c8257-7214-5efe-81d4-6d90ad564550"}, {"title": "常遇春重新占领吉安，进军赣州", "description": "常遇春遣人请饶鼎臣出城会面，饶鼎臣不敢出来，只派幼子前往。常遇春设座赐饮，又送给衣服，命其回去劝父亲及早作出打算。饶鼎臣当夜弃城逃走，常遇春重新占领吉安，随后领兵趋向赣州。", "start_year": 1364, "end_year": 1364, "time_original": "《续资治通鉴》卷218；本事原载纪年折合公元1364年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9e9615ae-85d7-5acf-9220-c85af5f7d66e"}, {"title": "徐达接受姜玨归降，并安抚江陵百姓", "description": "徐达、杨璟率军进攻江陵，驻于沙市。陈友谅旧平章姜玨前来请降，表示自己应当受死、百姓无罪。徐达赞许其言，下令安抚居民，禁止军队侵扰，各郡因而相继归附。后来，江陵路被改为荆州府。", "start_year": 1364, "end_year": 1364, "time_original": "《续资治通鉴》卷218；本事原载纪年折合公元1364年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "444e6d1a-c6b0-53ae-8ab2-56457fea69a1"}, {"title": "徐达军攻克辰州、衡州", "description": "徐达派张彬攻打辰州。张彬在白云关击败张川，周文贵弃辰州逃走，辰州被攻克。徐达又派傅友德进攻衡州，邓祖胜弃城退守永州，衡州也被平定。", "start_year": 1364, "end_year": 1364, "time_original": "《续资治通鉴》卷218；本事原载纪年折合公元1364年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0f234f03-142c-58ae-8603-73570e22c08e"}, {"title": "朱元璋送尹焕章返回汴梁，回赠库库特穆尔礼物", "description": "朱元璋派汪河送尹焕章返回汴梁，致信库库特穆尔，称赞其养父察罕特穆尔的智谋和勇气。他解释，先前派人到汴梁，主要是为了观察形势；如今感谢库库特穆尔送回使者并厚赠礼物，便回赠文绮，表示希望此后使者和商旅往来不绝。", "start_year": 1363, "end_year": 1363, "time_original": "《续资治通鉴》卷217；本事原载纪年折合公元1363年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "84ec19b5-fff1-5c19-b6ac-2f9ca75e7cbd"}, {"title": "朱元璋返回应天，常遇春留督诸军", "description": "十二月丙申，朱元璋返回应天，留下常遇春督领各路军队。", "start_year": 1364, "end_year": 1364, "time_original": "至正二十三年十二月", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "68b8fec0-9fb3-58e7-bc69-fa2d5e886f67"}, {"title": "朱元璋命在南昌建立忠臣祠", "description": "朱元璋命在南昌府建立忠臣祠，祭祀赵德胜等十四人。", "start_year": 1364, "end_year": 1364, "time_original": "《续资治通鉴》卷218；本事原载纪年折合公元1364年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b7b4638f-e21b-5774-b641-6646cb0d041a"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

